import React, { useEffect, useState } from "react";

function Search() {
  const [buses, setBuses] = useState([]);
  const [filteredBuses, setFilteredBuses] = useState([]);

  const [source, setSource] = useState("");
  const [destination, setDestination] = useState("");

  const [sortOption, setSortOption] = useState("");
  const [filterType, setFilterType] = useState("All");

  const popularRoutes = [
    { source: "Lucknow", destination: "Kanpur" },
    { source: "Varanasi", destination: "Prayagraj" },
    { source: "Gorakhpur", destination: "Lucknow" },
  ];

  // Fetch buses
  useEffect(() => {
    fetch("http://localhost:4000/api/buses")
      .then((res) => res.json())
      .then((data) => {
        setBuses(data);
        setFilteredBuses(data);
      })
      .catch((err) => console.error(err));
  }, []);

  const cheapestFare =
  filteredBuses.length > 0
    ? Math.min(...filteredBuses.map((bus) => bus.fare))
    : null;

// Start with filtered buses
let displayedBuses = [...filteredBuses];

// Apply Bus Type Filter
if (filterType !== "All") {
  displayedBuses = displayedBuses.filter(
    (bus) => bus.type === filterType
  );
}

// Apply Sorting
if (sortOption === "fareLow") {
  displayedBuses.sort((a, b) => a.fare - b.fare);
}

if (sortOption === "fareHigh") {
  displayedBuses.sort((a, b) => b.fare - a.fare);
}

if (sortOption === "timeEarly") {
  displayedBuses.sort(
    (a, b) =>
      new Date(`1970/01/01 ${a.time}`) -
      new Date(`1970/01/01 ${b.time}`)
  );
}

  const handleSearch = async () => {
    try {
      const res = await fetch(
        `http://localhost:4000/api/buses/search?source=${source}&destination=${destination}`
      );

      const data = await res.json();

      setFilteredBuses(data);
    } catch (err) {
      console.error(err);
    }
  };

  // Select popular route
const selectRoute = (src, dest) => {
  setSource(src);
  setDestination(dest);

  const results = buses.filter((bus) => {
    return (
      bus.route?.from?.toLowerCase().includes(src.toLowerCase()) &&
      bus.route?.to?.toLowerCase().includes(dest.toLowerCase())
    );
  });

  setFilteredBuses(results);
};

  return (
    <div className="bg-gray-100 min-h-screen">

      {/* Search Bar */}
      <div className="bg-blue-600 p-4 flex justify-center gap-4">
        <input
          placeholder="Source"
          value={source}
          onChange={(e) => setSource(e.target.value)}
          className="p-2 rounded"
        />

        <input
          placeholder="Destination"
          value={destination}
          onChange={(e) => setDestination(e.target.value)}
          className="p-2 rounded"
        />

        <button
          onClick={handleSearch}
          className="bg-white text-blue-600 px-4 py-2 rounded font-bold"
        >
          Search
        </button>
      </div>

      {/* Popular Routes */}
      <div className="max-w-6xl mx-auto mt-6 text-center">
        <h2 className="text-lg font-semibold mb-3">
          🔥 Popular Routes
        </h2>

        <div className="flex gap-4 justify-center flex-wrap">
          {popularRoutes.map((route, index) => (
            <button
              key={index}
              onClick={() => selectRoute(route.source, route.destination)}
              className="bg-white px-4 py-2 rounded shadow hover:bg-blue-100"
            >
              {route.source} → {route.destination}
            </button>
          ))}
        </div>
      </div>

      <div className="flex p-6 gap-6">

        {/* Filter Panel */}
        <div className="w-1/4 bg-white p-4 rounded shadow">

          <h2 className="font-bold text-lg mb-4">Filters</h2>

          <label className="block mb-2 font-semibold">
            Bus Type
          </label>

          <select
            className="border p-2 w-full mb-4"
            onChange={(e) => setFilterType(e.target.value)}
          >
            <option value="All">All</option>
            <option value="AC">AC</option>
            <option value="Ordinary">Ordinary</option>
            <option value="Volvo">Volvo</option>
          </select>

          <label className="block mb-2 font-semibold">
            Sort By
          </label>

          <select
            className="border p-2 w-full"
            onChange={(e) => setSortOption(e.target.value)}
          >
            <option value="">None</option>
            <option value="fareLow">Fare Low → High</option>
            <option value="fareHigh">Fare High → Low</option>
            <option value="timeEarly">Early Departure</option>
          </select>

        </div>


        {/* Bus Results */}
        <div className="w-3/4 space-y-4">

          {filteredBuses.length > 0 ? (
            displayedBuses.map((bus) => (
              <div
                key={bus._id}
                className={`bg-white p-5 rounded-lg shadow flex justify-between items-center ${
                  bus.fare === cheapestFare
                    ? "border-2 border-green-500 bg-green-50"
                    : ""
                }`}
              >

                <div>

                  <h2 className="text-lg font-bold">{bus.name}</h2>

                  <p className="text-gray-600">
                    🚏 {bus.route?.from} → {bus.route?.to}
                  </p>

                  <p className="text-gray-500">
                    🕒 Departure: {bus.time}
                  </p>

                  <p className="text-gray-500">
                    🚌 Type: {bus.type}
                  </p>

                </div>

                <div className="text-right">

                  <p className="text-green-600 text-xl font-bold">
                    ₹{bus.fare}
                  </p>

                  {bus.fare === cheapestFare && (
                    <p className="text-sm text-green-700 font-semibold">
                      ⭐ Cheapest
                    </p>
                  )}

                  <button className="mt-2 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">
                    View Seats
                  </button>

                </div>

              </div>
            ))
          ) : (
            <p>No buses found</p>
          )}

        </div>

      </div>
    </div>
  );
}

export default Search;
